import{_ as n,o as a,c as t,ag as i}from"./chunks/framework.W-j76G-U.js";const m=JSON.parse('{"title":"Lab 4 : prendre en main Claude Code","description":"","frontmatter":{},"headers":[],"relativePath":"handout-05-lab-4-claude-code.md","filePath":"handout-05-lab-4-claude-code.md","handout":{"fichier":"handout-05-lab-4-claude-code.md","markdown":"# Handout — Lab 4 : prendre en main Claude Code\\n\\n**Bootcamp AI-Driven Development · Module 0 · Zenika · support d\'exercice**\\n\\nLab optionnel (~30 min) : confier à Claude Code une tâche concrète sur un dépôt réel.\\n\\n## Rappel : Claude Code\\n\\n**Claude Code** est un agent Claude qui tourne dans votre terminal et pilote votre dépôt comme un développeur. Pour les profils tech, installable en une commande npm.\\n\\n- Naviguer dans un dépôt (même gros) avec le bon niveau de contexte.\\n- Écrire du code, modifier plusieurs fichiers, lancer les tests, corriger les erreurs.\\n- Exécuter des commandes shell, interagir avec Git, ouvrir une PR.\\n- Appeler des **MCP**, charger des **Skills** dédiées (SRE, DB, review, tests…).\\n- Fonctionner en **mode plan** ou en exécution directe.\\n\\nOù ça brille : refactor multi-fichiers, migration de framework, génération de tests sur du legacy, exploration d\'un dépôt inconnu, investigation d\'un bug via les logs.\\n\\n## Étapes\\n\\n1. **Choisir un petit dépôt** (perso ou side-project anonymisé). Installer Claude Code et le lancer à la racine du dépôt :\\n\\n```bash\\nnpm install -g @anthropic-ai/claude-code\\nclaude\\n```\\n\\n2. **Laisser explorer** : `/init` génère un `CLAUDE.md` (architecture, conventions, commandes).\\n\\n```text\\n/init\\n```\\n\\n3. **Choisir une mission de 15-30 min** : ajouter un test, renommer une fonction partout, documenter un module, corriger une typo dans 10 fichiers.\\n4. **Demander un plan** (mode plan) puis laisser exécuter. Observer : Claude Code lit, modifie, teste, explique.\\n5. **Relire le diff**, accepter / refuser, ouvrir une PR.\\n\\n> **Règle d\'or** : dépôt non critique, pas de secrets dans l\'historique, toujours relire le diff avant merge. Pas de dépôt client sans validation DSI.\\n"}}'),r={name:"handout-05-lab-4-claude-code.md"};function o(s,e,l,d,u,c){return a(),t("div",null,[...e[0]||(e[0]=[i(`<p class="zh-type">support d’exercice</p><h1 id="handout-lab-4-prendre-en-main-claude-code" tabindex="-1">Lab 4 : prendre en main Claude Code <a class="header-anchor" href="#handout-lab-4-prendre-en-main-claude-code" aria-label="Permalink to &quot;Handout — Lab 4 : prendre en main Claude Code&quot;">​</a></h1><p>Lab optionnel (~30 min) : confier à Claude Code une tâche concrète sur un dépôt réel.</p><h2 id="rappel-claude-code" tabindex="-1">Rappel : Claude Code <a class="header-anchor" href="#rappel-claude-code" aria-label="Permalink to &quot;Rappel : Claude Code&quot;">​</a></h2><p><strong>Claude Code</strong> est un agent Claude qui tourne dans votre terminal et pilote votre dépôt comme un développeur. Pour les profils tech, installable en une commande npm.</p><ul><li>Naviguer dans un dépôt (même gros) avec le bon niveau de contexte.</li><li>Écrire du code, modifier plusieurs fichiers, lancer les tests, corriger les erreurs.</li><li>Exécuter des commandes shell, interagir avec Git, ouvrir une PR.</li><li>Appeler des <strong>MCP</strong>, charger des <strong>Skills</strong> dédiées (SRE, DB, review, tests…).</li><li>Fonctionner en <strong>mode plan</strong> ou en exécution directe.</li></ul><p>Où ça brille : refactor multi-fichiers, migration de framework, génération de tests sur du legacy, exploration d’un dépôt inconnu, investigation d’un bug via les logs.</p><h2 id="etapes" tabindex="-1">Étapes <a class="header-anchor" href="#etapes" aria-label="Permalink to &quot;Étapes&quot;">​</a></h2><ol><li><strong>Choisir un petit dépôt</strong> (perso ou side-project anonymisé). Installer Claude Code et le lancer à la racine du dépôt :</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @anthropic-ai/claude-code</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude</span></span></code></pre></div><ol start="2"><li><strong>Laisser explorer</strong> : <code>/init</code> génère un <code>CLAUDE.md</code> (architecture, conventions, commandes).</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/init</span></span></code></pre></div><ol start="3"><li><strong>Choisir une mission de 15-30 min</strong> : ajouter un test, renommer une fonction partout, documenter un module, corriger une typo dans 10 fichiers.</li><li><strong>Demander un plan</strong> (mode plan) puis laisser exécuter. Observer : Claude Code lit, modifie, teste, explique.</li><li><strong>Relire le diff</strong>, accepter / refuser, ouvrir une PR.</li></ol><blockquote><p><strong>Règle d’or</strong> : dépôt non critique, pas de secrets dans l’historique, toujours relire le diff avant merge. Pas de dépôt client sans validation DSI.</p></blockquote>`,14)])])}const h=n(r,[["render",o]]);export{m as __pageData,h as default};
